import * as T from './vendor/three.module.js';
export function addFinishLine(scene,path){const station=path.length-12,group=new T.Group();group.name='Race finish line';for(let row=0;row<3;row++)for(let col=0;col<12;col++){const s=station+(row-1)*.55,o=(col-5.5)*.55,p=path.point(s,o),tile=new T.Mesh(new T.PlaneGeometry(.552,.552),new T.MeshBasicMaterial({color:(row+col)%2?0x17201e:0xfffdf3,side:T.DoubleSide}));tile.rotation.set(-Math.PI/2,0,0);tile.rotation.z=-Math.atan2(p.tx,-p.tz);tile.position.set(p.x,p.y+.065,p.z);group.add(tile);}const p=path.sample(station);for(const side of [-1,1]){const q=path.point(station,side*4),pole=new T.Mesh(new T.CylinderGeometry(.055,.055,4.5,6),new T.MeshLambertMaterial({color:0xe0e5df}));pole.position.set(q.x,q.y+2.25,q.z);group.add(pole);}const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=160;const c=canvas.getContext('2d');c.fillStyle='#142a23';c.fillRect(0,0,1024,160);c.fillStyle='#fff';c.font='bold 100px sans-serif';c.textAlign='center';c.fillText('FİNİŞ',512,118);const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;const board=new T.Mesh(new T.PlaneGeometry(7.8,1.05),new T.MeshBasicMaterial({map:texture,side:T.DoubleSide}));board.position.set(p.x,p.y+4.05,p.z);board.rotation.y=Math.atan2(-p.tx,-p.tz);group.add(board);scene.add(group);return group;}
export class RemoteDriver{
 constructor(scene){this.root=new T.Group();this.root.visible=false;this.target=new T.Vector3();this.rotation=new T.Quaternion();this.last=0;const body=new T.Mesh(new T.BoxGeometry(1.57,.4,3.56),new T.MeshLambertMaterial({color:0x3888db}));this.root.add(body);const cabin=new T.Mesh(new T.BoxGeometry(1.3,.63,1.75),new T.MeshLambertMaterial({color:0x355b72}));cabin.position.set(0,.43,-.22);this.root.add(cabin);for(const x of [-.8,.8])for(const z of [-1.1,1.1]){const tire=new T.Mesh(new T.CylinderGeometry(.38,.38,.25,14),new T.MeshLambertMaterial({color:0x202722}));tire.rotation.z=Math.PI/2;tire.position.set(x,-.16,z);this.root.add(tire);}scene.add(this.root);}
 receive(packet){this.target.fromArray(packet.p);this.rotation.fromArray(packet.q).normalize();if(!this.root.visible){this.root.position.copy(this.target);this.root.quaternion.copy(this.rotation);}this.last=performance.now();this.root.visible=true;this.packet=packet;}
 update(dt){if(performance.now()-this.last>4000){this.root.visible=false;return;}this.root.position.lerp(this.target,1-Math.exp(-12*dt));this.root.quaternion.slerp(this.rotation,1-Math.exp(-12*dt));}
 hide(){this.root.visible=false;this.last=0;}
}
